// 3D model of the uploaded floor plan, generated by the RoomFit floor plan service
// (floorplan3d-service/: CubiCasa5K recognition + 3D extrusion, hosted on Hugging Face).
import { RoomKind } from "./types";

const API = process.env.EXPO_PUBLIC_BACKEND_URL;

export interface Plan3DRoom {
  label: string;
  type: RoomKind;
  area_m2: number;
  area_sqft: number;
  centroid: [number, number]; // metres; x right, y down (= glTF x, z)
  confidence: number;
  why: string;
}

export interface Plan3DResult {
  glbBase64: string;
  rooms: Plan3DRoom[];
  doors: number;
  windows: number;
  totalSqft: number;
  scaleSource: string;
  wallHeight: number;
}

// Floor colours used in the 3D model (floorplan3d-service/roomfit_3d.py FLOOR_COLORS), for legends.
export const ROOM_COLORS: Record<string, string> = {
  living: "#D6B88C", bedroom: "#A0BED2", kitchen: "#E2B26E", bathroom: "#DEA0A0",
  hallway: "#D6CC8C", closet: "#BEA582", balcony: "#A0C496", dining: "#D6B88C", other: "#CDC8BE",
};

const cache = new Map<string, Plan3DResult>();

export const backendConfigured = () => !!API;

export async function generate3D(imageDataUri: string, sqft: number | null, wallHeight: number, signal?: AbortSignal): Promise<Plan3DResult> {
  if (!API) throw new Error("The floor plan server address is missing. Add EXPO_PUBLIC_BACKEND_URL to frontend/.env and restart Expo.");
  const key = `${imageDataUri.length}:${imageDataUri.slice(-64)}|${sqft}|${wallHeight}`;
  const hit = cache.get(key);
  if (hit) return hit;
  let res: Response;
  try {
    res = await fetch(`${API}/api/floorplan/3d`, {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify({ image_base64: imageDataUri, sqft, wall_height: wallHeight }),
      signal,
    });
  } catch (e) {
    if ((e as Error)?.name === "AbortError") throw e;
    throw new Error("Could not reach the floor plan server. Check your internet connection and try again.");
  }
  if (!res.ok) {
    let detail = "";
    try {
      detail = (await res.json()).detail;
    } catch {}
    throw new Error(typeof detail === "string" && detail ? detail : `The server could not build a 3D model (error ${res.status}).`);
  }
  const d = await res.json();
  const fp = d.floorplan;
  const out: Plan3DResult = {
    glbBase64: d.glb_base64,
    rooms: fp.rooms,
    doors: fp.doors.length,
    windows: fp.windows.length,
    totalSqft: fp.total_room_area_sqft,
    scaleSource: fp.scale_source,
    wallHeight: fp.wall_height_m,
  };
  cache.set(key, out);
  return out;
}
